<script lang="ts">import {publicLabels} from '$lib/content/public';let {data,form}=$props();function pageHref(page:number){const q=new URLSearchParams();for(const [k,v]of Object.entries(data.filter))if(Array.isArray(v)){for(const id of v)q.append('tag',id);}else if(v!==undefined)q.set(k,String(v));q.set('page',String(page));return '?'+q;}</script>
<svelte:head><title>内容 · 站长工作台</title></svelte:head><main><h1>内容</h1>{#if form?.error}<p role="alert">{form.error}</p>{/if}{#if form?.success}<p role="status">{form.success}</p>{/if}
<form method="post" action="?/create"><label>新建类型<select name="type">{#each Object.entries(publicLabels) as [value,label]}<option {value}>{label}</option>{/each}</select></label><button>新建内容</button></form>
<form method="get"><label>类型<select name="type" value={data.filter.type??''}><option value="">全部</option>{#each Object.entries(publicLabels) as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>公开状态<select name="published" value={data.filter.published??''}><option value="">全部</option><option value="yes">已公开</option><option value="no">未公开</option></select></label><label>归档<select name="archived" value={data.filter.archived??''}><option value="all">全部</option><option value="no">未归档</option><option value="yes">已归档</option></select></label><label>排期<select name="schedule" value={data.filter.schedule??''}><option value="">全部</option><option value="none">无活动排期</option><option value="pending">待执行</option><option value="running">执行中</option><option value="retrying">重试中</option><option value="failed">失败</option></select></label><label>编辑状态<select name="editing" value={data.filter.editing??''}><option value="">全部</option><option value="changed">有未发布修改</option><option value="same">与公开版一致</option><option value="draft">未发布草稿</option></select></label><label>关键词<input name="q" value={data.filter.q} maxlength="100"/></label><fieldset><legend>标签（任一匹配）</legend>{#each data.tags as tag}<label class="check"><input type="checkbox" name="tag" value={tag.id} checked={data.filter.tags.includes(tag.id)}/>{tag.name}</label>{/each}</fieldset><button>应用筛选</button></form>
<p>共 {data.total} 条 · 第 {data.page} 页</p><ul>{#each data.items as item}<li><a href={`/workspace/content/${item.id}/edit`}>{item.title.slice(0,100)}</a><p>{item.type} · {item.public_version_id?'已公开':item.first_published_at?'已撤回':'从未发布'} · {({changed:'有未发布修改',same:'与公开版一致',draft:'未发布草稿'})[item.editing]} · {item.archived?'已归档':'未归档'}{item.schedule_status?` · 排期 ${item.schedule_status}`:''}</p><p>最后编辑：{item.updated_at?new Date(item.updated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'尚未保存'} · 首次公开：{item.first_published_at?new Date(item.first_published_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'尚未发布'}</p>{#if item.public_version_id&&item.slug}<a href={`/${({article:'articles',note:'notes',moment:'moments',project:'projects',tool:'tools',resource:'resources'})[item.type]}/${item.slug}`}>查看公开页</a>{/if}<a href={`/workspace/content/${item.id}/publish`}>发布设置</a>{#if item.schedule_id}<a href={`/workspace/schedules/${item.schedule_id}`}>处理排期</a>{/if}<form method="post" action="?/archive"><input type="hidden" name="id" value={item.id}/><input type="hidden" name="archived" value={item.archived?'no':'yes'}/><button>{item.archived?'取消归档':'归档（不撤回）'}</button></form></li>{/each}</ul>{#if !data.items.length}<p>当前条件没有内容。</p>{/if}<nav aria-label="内容分页">{#if data.page>1}<a href={pageHref(data.page-1)}>上一页</a>{/if}{#if data.page*20<data.total}<a href={pageHref(data.page+1)}>下一页</a>{/if}</nav></main>
<style>form{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin-block:20px}label{min-width:150px}ul{list-style:none;padding:0}li{border-top:1px solid var(--line);padding:20px 0;overflow-wrap:anywhere}li a{margin-right:16px}nav{display:flex;gap:24px}</style>
